 }
 public class Fighter {
  public Pokemon Data; public string AA="", Status="정상",OriginalAbility="",CurrentAbility=""; public bool AbilityChanged,AbilitySuppressed,OnField=true;public int HP; public int[] Stages=new int[6]; public int AccuracyStage,EvasionStage,CriticalStage; public double AccuracyMultiplier=1,EvasionMultiplier=1; public double[] Multipliers={1,1,1,1,1,1};
  public string[] Moves; public int Selected; public ConditionState Conditions=new ConditionState();
  public Fighter(Pokemon p){Data=ClonePokemon(p);Moves=(p.moves??new string[0]).Take(4).ToArray();OriginalAbility=CurrentAbility=p.ability??"";HP=Engine.Stats(this,p.level,new Rules())[0];}
  public Fighter Copy(){var f=new Fighter(Data);f.AA=AA;f.Status=Status;f.OriginalAbility=OriginalAbility;f.CurrentAbility=CurrentAbility;f.AbilityChanged=AbilityChanged;f.AbilitySuppressed=AbilitySuppressed;f.OnField=OnField;f.HP=HP;f.Stages=(int[])Stages.Clone();f.AccuracyStage=AccuracyStage;f.EvasionStage=EvasionStage;f.CriticalStage=CriticalStage;f.AccuracyMultiplier=AccuracyMultiplier;f.EvasionMultiplier=EvasionMultiplier;f.Multipliers=(double[])Multipliers.Clone();f.Moves=(string[])Moves.Clone();f.Selected=Selected;f.Conditions=Conditions.Copy();return f;}
