  public class TurnResult { public Rules Rules; public Fighter[] Fighters;public Fighter[] SwitchedOut=new Fighter[2];public TrainerBattleState[] Trainers;public bool[] Switched=new bool[2];public List<SwitchRecord> Switches=new List<SwitchRecord>();public List<string> Log=new List<string>(); }
 public static class Engine {
  public static readonly string[] Names={"체력","공격","방어","특공","특방","속도"};
  public static int[] Stats(Fighter f,int other,Rules r){var p=f.Data;int low=Math.Min(p.level,other);double c=1+Math.Max(0,p.level-other)*r.LevelCorrection/100;return p.@base.Select((v,i)=>{int species=v+(i==0?PrivilegeRules.HpBonus(f,r):0);return i==0?(int)(r.HPCorrection?Math.Floor((Math.Floor((species*2+p.iv[i])*low/100.0)+10+low)*c):Math.Floor((species*2+p.iv[i])*p.level/100.0+10+p.level)):(int)Math.Floor((Math.Floor((species*2+p.iv[i])*low/100.0)+5)*c);}).ToArray();}
  public static double Stage(int n){return n>=0?(2+n)/2.0:2.0/(2-n);}
  public static int Effective(Fighter a,Fighter b,int i,Rules r,int role=0,int side=-1){return EffectiveAtLevel(a,b,b.Data.level,i,r,role,side);}
  public static int EffectiveAtLevel(Fighter a,Fighter environmentOpponent,int otherLevel,int i,Rules r,int role=0,int side=-1){int s=a.Stages[i];double m=a.Multipliers[i];if(r.Critical&&role==1){s=Math.Max(0,s);m=Math.Max(1,m);}if(r.Critical&&role==2){s=Math.Min(0,s);m=Math.Min(1,m);}return Math.Max(1,(int)Math.Floor(Stats(a,otherLevel,r)[i]*m*Stage(s)*Mechanics.StatFactor(a,environmentOpponent,i,r,side)));}
  public static double Match(Database db,string[] at,string[] dt){return at.Length==0?1:at.Max(t=>dt.Aggregate(1.0,(n,d)=>n*(db.chart.ContainsKey(d)&&db.chart[d].ContainsKey(t)?db.chart[d][t]:1)));}
  public static Damage Calculate(Database db,Fighter a,Fighter b,Move m,Rules r,int attackerSide=-1){
   Rules active=r;if(r.Critical&&AbilityRuntime.BlocksCritical(a,b)){active=r.Copy();active.Critical=false;}
   int ai=Math.Max(1,Array.IndexOf(Names,m.attack??(m.category=="물리"?"공격":"특공"))),di=Math.Max(1,Array.IndexOf(Names,m.defense??(m.category=="물리"?"방어":"특방")));
   double power=Math.Max(0,Math.Floor(m.power+active.PowerBonus)*active.PowerMultiplier);
   power*=Mechanics.PowerFactor(a,b,m,active)*AbilityRuntime.Power(a,m);
   double normalStab=active.Stab>0?active.Stab:m.types.Any(t=>a.Data.types.Contains(t))?1.5:1,stab=AbilityRuntime.Stab(a,normalStab),type=Mechanics.TypeEffect(db,a,b,m,active);
   string reason=Mechanics.Block(db,a,b,m,active);if(reason.Length>0)type=0;
   int defenderSide=attackerSide>=0&&attackerSide<2?1-attackerSide:-1;double basis=Math.Floor(((2*a.Data.level+10)/250.0*Effective(a,b,ai,active,1,attackerSide)/Effective(b,a,di,active,2,defenderSide)*power+2)*stab*type*(active.Critical?2:1)*active.DamageMultiplier*Mechanics.DamageFactor(a,b,m,active,defenderSide)*AbilityRuntime.Damage(a,b,active));
   bool supported=m.category!="변화"&&m.power>0;
   int[] rolls=Enumerable.Range(85,16).Select(v=>supported?(int)Math.Min(int.MaxValue,Math.Floor(basis*v/100)):0).ToArray();
   return new Damage{Min=rolls[0],Max=rolls[15],Rolls=rolls,Stab=stab,Type=type,Supported=supported,Reason=reason};
  }
  public static Damage CalculateDelayed(Database db,Fighter target,Fighter environmentOpponent,DelayedAttackState delayed,Rules r){
   var m=delayed.Move;int di=Math.Max(1,Array.IndexOf(Names,m.defense??"특방"));
   double power=Math.Max(0,Math.Floor(m.power));
   var source=Mechanics.DelayedSource(delayed);
   double stab=(delayed.SourceTypes??new string[0]).Any(t=>(m.types??new string[0]).Contains(t))?1.5:1;
   double type=Mechanics.TypeEffect(db,source,target,m,r);
   int defense=EffectiveAtLevel(target,environmentOpponent,delayed.SourceLevel,di,r,2);
   double basis=Math.Floor(((2*delayed.SourceLevel+10)/250.0*delayed.SourceSpecialAttack/defense*power+2)*stab*type*Mechanics.DelayedDamageFactor(target,m));
   bool supported=m.category!="변화"&&m.power>0;
   int[] rolls=Enumerable.Range(85,16).Select(v=>supported?(int)Math.Min(int.MaxValue,Math.Floor(basis*v/100)):0).ToArray();
   return new Damage{Min=rolls[0],Max=rolls[15],Rolls=rolls,Stab=stab,Type=type,Supported=supported};
  }
  public static TurnResult Resolve(Database db,Fighter[] input,Move[] moves,Rules original,Func<double> rng){
   var commands=moves.Select(m=>new BattleCommand{Move=m}).ToArray();return Resolve(db,input,commands,original,new[]{new TrainerBattleState(),new TrainerBattleState()},rng,null);
  }
  public static TurnResult Resolve(Database db,Fighter[] input,BattleCommand[] commands,Rules original,TrainerBattleState[] trainerInput,Func<double> rng){
   return Resolve(db,input,commands,original,trainerInput,rng,null);
  }
  public static TurnResult Resolve(Database db,Fighter[] input,BattleCommand[] commands,Rules original,TrainerBattleState[] trainerInput,Func<double> rng,Func<SwitchRequest,Fighter> chooseSwitch){
   if(input==null||input.Length!=2||commands==null||commands.Length!=2)throw new Exception("양쪽 행동을 모두 선택하세요.");
   var states=(trainerInput??new[]{new TrainerBattleState(),new TrainerBattleState()}).Select(x=>(x??new TrainerBattleState()).Copy()).ToArray();
   var result=new TurnResult{Fighters=input.Select(p=>p.Copy()).ToArray(),Rules=original.Copy(),Trainers=states};var f=result.Fighters;var r=result.Rules;int[] deployed={-1,-1};bool[] returnAway={false,false};for(int i=0;i<2;i++)f[i].OnField=true;
   AbilityRuntime.RefreshSuppression(f,result.Log.Add);EnterAbilities(f,r,rng,i=>!f[i].Conditions.AbilityEntryApplied,result.Log);
   for(int i=0;i<2;i++){
    var c=commands[i]??new BattleCommand();string form=c.Form??"",order=c.Order??"";
    if(c.IsSwitch&&form.Length>0&&!form.Contains("돌아와"))throw new Exception("교대 행동에는 『돌아와!』만 함께 선언할 수 있습니다.");
    if(!c.IsSwitch&&form.Contains("돌아와"))throw new Exception("『돌아와!』는 교대 행동과 함께 선언하세요.");
    if(c.IsSwitch&&order.Length>0)throw new Exception("지령은 기술 선택과 함께 선언하세요.");
    if(!c.IsSwitch&&c.Move==null)throw new Exception("기술 또는 교대 행동을 선택하세요.");
    if(form.Length>0){if(states[i].UsedForms.Contains(form))throw new Exception(form+"은 이미 사용했습니다.");states[i].UsedForms.Add(form);result.Log.Add("TRAINER "+(i+1)+" — 『"+form+"』 선언!");}
    if(order.Length>0){if(states[i].UsedOrders.Contains(order))throw new Exception(order+"은 이미 사용했습니다.");states[i].UsedOrders.Add(order);result.Log.Add("TRAINER "+(i+1)+" — 『"+order+"』 지령!");deployed[i]=ApplyOrder(f[i],f[1-i],order,r,result.Log);if(deployed[i]==-2)c.Move=null;}
    foreach(string potential in c.PreInputs??new string[0]){var definition=(f[i].Data.potentials??new Potential[0]).FirstOrDefault(x=>x!=null&&x.name==potential);bool limited=definition!=null&&(definition.uses??"").Contains("1/");if(limited&&states[i].UsedPotentials.Contains(potential))throw new Exception("『"+potential+"』은 이미 사용했습니다.");if(limited)states[i].UsedPotentials.Add(potential);result.Log.Add(f[i].Data.name+" — 선행입력 『"+potential+"』 선언!"+((definition==null?"":definition.description)??""));}
    if(order.Length>0){RuntimeTriggers.DirectiveReceived(f[i],(c.Party??new Fighter[0]).Where(x=>x!=null&&x.Data.name!=f[i].Data.name).Concat(new[]{f[i]}),order,result.Log.Add);TrainerTriggers.Fire(states[i].Trainer,TriggerStructures.AllyOrderLabel,order,result.Log.Add);}
   }
    AnsweredTriggers.Selected(f,commands,result.Log.Add);int entryStart=result.Log.Count;
    for(int i=0;i<2;i++)if(commands[i].IsSwitch&&(commands[i].Form??"").Contains("돌아와")){Fighter outgoing=f[i].Copy();RuntimeTriggers.Switch(f[i],SwitchReason.Return,result.Log.Add);AbilityRuntime.Leave(f[i],f[1-i],r,SwitchReason.Return,result.Log);f[i].OnField=false;result.SwitchedOut[i]=outgoing;returnAway[i]=true;result.Log.Add("『돌아와!』 — "+f[i].Data.name+"을 먼저 볼로 되돌렸다!");}
   AbilityRuntime.RefreshSuppression(f,result.Log.Add);
     for(int i=0;i<2;i++)if(commands[i].IsSwitch&&!((commands[i].Form??"").Contains("돌아와"))){Fighter outgoing=f[i].Copy();RuntimeTriggers.Switch(f[i],SwitchReason.Normal,result.Log.Add);AbilityRuntime.Leave(f[i],f[1-i],r,SwitchReason.Normal,result.Log);f[i].OnField=false;result.SwitchedOut[i]=outgoing;f[i]=commands[i].SwitchIn.Copy();f[i].OnField=true;result.Fighters=f;result.Switched[i]=true;result.Switches.Add(new SwitchRecord{Side=i,Timing=SwitchTiming.MidTurn,Reason=SwitchReason.Normal,Source="통상 교대",Outgoing=outgoing,Incoming=f[i].Copy()});Mechanics.EnterField(db,f[i],f[1-i],i,r,rng,result.Log);EntryTriggers.Enter(f[i],EntryReason.NormalSwitch,result.Log.Add);RuntimeTriggers.OpponentEntered(f[1-i],f[i],result.Log.Add);result.Log.Add("TRAINER "+(i+1)+"의 통상 교대 — "+f[i].Data.name+" 등장!");}
