    string reason=target?Mechanics.Block(db,a,b,m,r):"";
     if(reason.Length>0){result.Log.Add(a.Data.name+"의 "+m.name+" — "+reason);Mechanics.Absorb(a,b,reason,r,result.Log);RuntimeTriggers.Nullified(b,a,m,reason,result.Log.Add);AnsweredTriggers.DefensiveBlocked(b,a,m,reason,result.Log.Add);ResolveTriggeredSwitches(db,f,commands,states,r,rng,result,actionStart,SwitchTiming.MidTurn,chooseSwitch);continue;}
     if(target&&b.Conditions.Substitute>0&&m.category=="변화"&&!Mechanics.BypassSub(a,m)){result.Log.Add("대타가 "+m.name+"을 막았다.");ResolveTriggeredSwitches(db,f,commands,states,r,rng,result,actionStart,SwitchTiming.MidTurn,chooseSwitch);continue;}
     bool sureHit=(commands[i].Form??"").Contains("맞춰라");if(!sureHit&&rng()*100>=Mechanics.Accuracy(a,b,m,r)){result.Log.Add(a.Data.name+"의 "+m.name+"! 그러나 빗나갔다!");ResolveTriggeredSwitches(db,f,commands,states,r,rng,result,actionStart,SwitchTiming.MidTurn,chooseSwitch);continue;}
     if(m.category=="변화"){Mechanics.StatusMove(a,b,m,r,rng,result.Log,i);ResolveTriggeredSwitches(db,f,commands,states,r,rng,result,actionStart,SwitchTiming.MidTurn,chooseSwitch);if(f[i]==a&&a.HP>0&&(SwitchEffectRuntime.IsPivotMove(m)||pivotGrant))RequestSwitch(db,f,commands,states,r,rng,result,i,SwitchReason.Pivot,SwitchTiming.MidTurn,m.name,chooseSwitch);continue;}
