     if(bodyDamage>0)TrainerTriggers.Fire(states[1-i].Trainer,TriggerStructures.DamagedLabel,a.Data.name+"의 "+m.name+"으로 "+bodyDamage+" 대미지",result.Log.Add);if(b.HP==0)TrainerTriggers.Fire(states[i].Trainer,TriggerStructures.DefeatLabel,b.Data.name+"을 직접 쓰러뜨림",result.Log.Add);TrainerTriggers.Fire(states[i].Trainer,TriggerStructures.AttackSuccessLabel,m.name+" 공격 성공",result.Log.Add);AbilityRuntime.RefreshSuppression(f,result.Log.Add);
     ResolveTriggeredSwitches(db,f,commands,states,r,rng,result,actionStart,SwitchTiming.MidTurn,chooseSwitch);
     if(f[i]==a&&a.HP>0&&(SwitchEffectRuntime.IsPivotMove(m)||pivotGrant))RequestSwitch(db,f,commands,states,r,rng,result,i,SwitchReason.Pivot,SwitchTiming.MidTurn,m.name,chooseSwitch);
    }
    for(int i=0;i<2;i++)if(returnAway[i]){f[i]=commands[i].SwitchIn.Copy();f[i].OnField=true;result.Fighters=f;result.Switched[i]=true;result.Switches.Add(new SwitchRecord{Side=i,Timing=SwitchTiming.TurnEnd,Reason=SwitchReason.Return,Source="『돌아와!』",Outgoing=result.SwitchedOut[i],Incoming=f[i].Copy()});Mechanics.EnterField(db,f[i],f[1-i],i,r,rng,result.Log);EntryTriggers.Enter(f[i],EntryReason.Return,result.Log.Add);RuntimeTriggers.OpponentEntered(f[1-i],f[i],result.Log.Add);TrainerTriggers.Fire(states[i].Trainer,TriggerStructures.EntryLabel,f[i].Data.name+"이 장소에 나옴",result.Log.Add,f[i]);TrainerTriggers.Fire(states[1-i].Trainer,TriggerStructures.OpponentEntryLabel,f[i].Data.name+"이 상대 장소에 나옴",result.Log.Add,f[1-i]);result.Log.Add("『돌아와!』 — 턴 마지막 교대 시점에 "+f[i].Data.name+" 등장!");}
   AbilityRuntime.RefreshSuppression(f,result.Log.Add);EnterAbilities(f,r,rng,i=>result.Switched[i]&&(commands[i].Form??"").Contains("돌아와"),result.Log);
    int turnEndStart=result.Log.Count;Mechanics.EndTurn(f,r,result.Log,rng);foreach(int i in Mechanics.SpeedOrder(f,r,rng))AbilityRuntime.EndTurn(f[i],f[1-i],r,result.Log);for(int i=0;i<2;i++)if(!result.Switched[i]){if(deployed[i]>=0)f[i].Multipliers[deployed[i]]/=2;else if(deployed[i]==-3)f[i].AccuracyMultiplier/=2;else if(deployed[i]==-4)f[i].EvasionMultiplier/=2;}RuntimeTriggers.TurnEnd(f,r,rng,result.Log.Add);for(int i=0;i<2;i++)TrainerTriggers.Fire(states[i].Trainer,TriggerStructures.TurnEndLabel,"턴 종료",result.Log.Add);ResolveTriggeredSwitches(db,f,commands,states,r,rng,result,turnEndStart,SwitchTiming.TurnEnd,chooseSwitch);int delayedStart=result.Log.Count;Mechanics.ResolveDelayedMoves(db,f,r,rng,result.Log,(side,attack,damage,defeated)=>{if(damage>0)TrainerTriggers.Fire(states[1-side].Trainer,TriggerStructures.DamagedLabel,attack.SourceName+"의 "+attack.Move.name+"으로 "+damage+" 대미지",result.Log.Add);});ResolveTriggeredSwitches(db,f,commands,states,r,rng,result,delayedStart,SwitchTiming.TurnEnd,chooseSwitch);return result;
