   static void ResolveTriggeredSwitches(Database db,Fighter[] fighters,BattleCommand[] commands,TrainerBattleState[] states,Rules rules,Func<double> rng,TurnResult result,int logStart,SwitchTiming timing,Func<SwitchRequest,Fighter> chooseSwitch){var lines=result.Log.Skip(Math.Max(0,logStart)).ToArray();for(int side=0;side<2;side++){Fighter owner=fighters[side];if(owner==null||owner.HP<=0||!owner.OnField)continue;BattleCommand command=commands[side]??new BattleCommand();foreach(var potential in SwitchEffectRuntime.TriggeredSwitches(owner,lines)){bool limited=SwitchEffectRuntime.Limited(potential),declared=(command.PreInputs??new string[0]).Contains(potential.name);if(limited&&states[side].UsedPotentials.Contains(potential.name)&&!declared)continue;string source="『"+potential.name+"』";if(RequestSwitch(db,fighters,commands,states,rules,rng,result,side,SwitchReason.Potential,timing,source,chooseSwitch)){if(limited)states[side].UsedPotentials.Add(potential.name);break;}}if(fighters[side]!=owner||fighters[side].HP<=0||!fighters[side].OnField)continue;foreach(var potential in SwitchEffectRuntime.TriggeredTrainerSwitches(states[side].Trainer,lines)){bool limited=(potential.uses??"").Contains("1/");if(limited&&states[side].UsedPotentials.Contains(potential.name))continue;string source="TRAINER 『"+potential.name+"』";if(RequestSwitch(db,fighters,commands,states,rules,rng,result,side,SwitchReason.Potential,timing,source,chooseSwitch)){if(limited)states[side].UsedPotentials.Add(potential.name);break;}}}}
   static Fighter[] SwitchCandidates(Fighter current,BattleCommand command){var seen=new HashSet<string>();return (command==null?new Fighter[0]:(command.Party??new Fighter[0])).Where(x=>x!=null&&x.Data!=null&&x.HP>0&&current!=null&&x.Data.name!=current.Data.name&&seen.Add(x.Data.name)).Select(x=>x.Copy()).ToArray();}
   static bool RequestSwitch(Database db,Fighter[] fighters,BattleCommand[] commands,TrainerBattleState[] states,Rules rules,Func<double> rng,TurnResult result,int side,SwitchReason reason,SwitchTiming timing,string source,Func<SwitchRequest,Fighter> chooseSwitch){if(side<0||side>1||fighters[side]==null||fighters[side].HP<=0||!fighters[side].OnField)return false;var candidates=SwitchCandidates(fighters[side],commands[side]);if(candidates.Length==0){result.Log.Add(fighters[side].Data.name+"의 "+source+" — 교대할 수 있는 아군이 없다.");return false;}var request=new SwitchRequest{Side=side,Timing=timing,Source=source,Outgoing=fighters[side].Copy(),Candidates=candidates};Fighter selected=chooseSwitch==null?null:chooseSwitch(request);if(selected==null){result.Log.Add(fighters[side].Data.name+"의 "+source+" — 교대를 취소했다.");return false;}var incoming=candidates.FirstOrDefault(x=>x.Data.name==selected.Data.name);if(incoming==null){result.Log.Add(fighters[side].Data.name+"의 "+source+" — 교대 대상이 유효하지 않아 취소했다.");return false;}SwitchNow(db,fighters,states,rules,rng,result,side,incoming,reason,timing,source);return true;}
   static void SwitchNow(Database db,Fighter[] fighters,TrainerBattleState[] states,Rules rules,Func<double> rng,TurnResult result,int side,Fighter incoming,SwitchReason reason,SwitchTiming timing,string source){Fighter outgoing=fighters[side].Copy();RuntimeTriggers.Switch(fighters[side],reason,result.Log.Add);AbilityRuntime.Leave(fighters[side],fighters[1-side],rules,reason,result.Log);fighters[side].OnField=false;result.SwitchedOut[side]=outgoing;fighters[side]=incoming.Copy();fighters[side].OnField=true;result.Fighters=fighters;result.Switched[side]=true;result.Switches.Add(new SwitchRecord{Side=side,Timing=timing,Reason=reason,Source=source,Outgoing=outgoing,Incoming=fighters[side].Copy()});Mechanics.EnterField(db,fighters[side],fighters[1-side],side,rules,rng,result.Log);EntryTriggers.Enter(fighters[side],reason==SwitchReason.Pivot?EntryReason.Pivot:EntryReason.Potential,result.Log.Add);RuntimeTriggers.OpponentEntered(fighters[1-side],fighters[side],result.Log.Add);TrainerTriggers.Fire(states[side].Trainer,TriggerStructures.EntryLabel,fighters[side].Data.name+"이 장소에 나옴",result.Log.Add,fighters[side]);TrainerTriggers.Fire(states[1-side].Trainer,TriggerStructures.OpponentEntryLabel,fighters[side].Data.name+"이 상대 장소에 나옴",result.Log.Add,fighters[1-side]);AbilityRuntime.RefreshSuppression(fighters,result.Log.Add);AbilityRuntime.Enter(fighters[side],fighters[1-side],rules,result.Log.Add);result.Log.Add(source+" — "+(timing==SwitchTiming.TurnEnd?"턴 마지막":"턴 중간")+"에 "+fighters[side].Data.name+" 등장!");}
   static void EnterAbilities(Fighter[] fighters,Rules rules,Func<double> rng,Func<int,bool> include,List<string> log){var sides=Enumerable.Range(0,2).Where(include).ToArray();if(sides.Length==2)sides=Mechanics.SpeedOrder(fighters,rules,rng);foreach(int side in sides)AbilityRuntime.Enter(fighters[side],fighters[1-side],rules,log.Add);}
  static int ApplyOrder(Fighter a,Fighter b,string order,Rules r,List<string> log){
   bool deploy=order.Contains("전개");if(order.Contains("회복")){int max=Stats(a,b.Data.level,r)[0],amount=Math.Max(1,max/(deploy?2:4));int before=a.HP;a.HP=Math.Min(max,a.HP+amount);int gain=a.HP-before;log.Add(a.Data.name+"의 HP가 "+gain+" 회복됐다."+(deploy?" 행동은 생략된다.":""));AnsweredTriggers.Healed(a,gain,order,log.Add);return deploy?-2:-1;}
   if(order.Contains("저격")||order.Contains("명중")){if(deploy){a.AccuracyMultiplier*=2;log.Add(a.Data.name+": 명중 2배(이번 턴)");return -3;}int before=a.AccuracyStage;a.AccuracyStage=Math.Min(6,a.AccuracyStage+1);AnsweredTriggers.StageChanged(a,b,6,before,a.AccuracyStage,log.Add);log.Add(a.Data.name+": 명중 +1");return -1;}
   if(order.Contains("회피")){if(deploy){a.EvasionMultiplier*=2;log.Add(a.Data.name+": 회피 2배(이번 턴)");return -4;}int before=a.EvasionStage;a.EvasionStage=Math.Min(6,a.EvasionStage+1);AnsweredTriggers.StageChanged(a,b,7,before,a.EvasionStage,log.Add);log.Add(a.Data.name+": 회피 +1");return -1;}
   string[] labels={"공격","방어","특공","특방","민첩","속도"};int[] indexes={1,2,3,4,5,5};int at=Array.FindIndex(labels,x=>order.Contains(x));if(at<0)return -1;int stat=indexes[at];if(deploy){a.Multipliers[stat]*=2;log.Add(a.Data.name+": "+Names[stat]+" 2배(이번 턴)");return stat;}Mechanics.ChangeStage(a,b,stat,1,r,order,log);return -1;
  }
  static Fighter TriggerFighter(Fighter source,string name,string potential,string trigger){var p=source.Data;return new Fighter(new Pokemon{id="trigger-test",name=name,level=p.level,@base=(int[])p.@base.Clone(),iv=(int[])p.iv.Clone(),types=(string[])p.types.Clone(),moves=(string[])p.moves.Clone(),potentials=new[]{new Potential{name=potential,description="공격이 오른다.",triggers=new[]{trigger}}}});}
